cd /app && python - <<'PY'
import numpy as np,time
N=3000
for n in [2,4,6,8,10]:
 def bench(f):
  ts=[]
  for _ in range(N):
   A=np.random.normal(size=(n,n))
   t=time.perf_counter(); f(A); ts.append(time.perf_counter()-t)
  return np.median(ts)
 def ref(A):
  w,v=np.linalg.eig(A); i=np.argmax(np.abs(w)); return w[i],v[:,i]
 def ev(A):
  w=np.linalg.eigvals(A); i=np.argmax(np.abs(w)); return w[i]
 def svd(A):
  w=np.linalg.eigvals(A); i=np.argmax(np.abs(w)); l=w[i]
  u,s,vh=np.linalg.svd(A-l*np.eye(n)); return l,vh[-1].conj()
 def solve(A):
  w=np.linalg.eigvals(A); i=np.argmax(np.abs(w)); l=w[i]
  M=A-l*np.eye(n)
  M[0,0]+=1e-12*np.linalg.norm(A)
  b=np.ones(n); x=np.linalg.solve(M,b); return l,x/np.linalg.norm(x)
 print(n,'ref',bench(ref),'ev',bench(ev),'svd',bench(svd),'solve',bench(solve))
