cd /app && python - <<'PY'
import numpy as np,time
import scipy.linalg as sla
from scipy.linalg.lapack import dgeev
N=2000
for n in [2,4,6,8,10]:
 def bench(f):
  ts=[]
  for _ in range(N):
   A=np.random.normal(size=(n,n))
   t=time.perf_counter(); f(A); ts.append(time.perf_counter()-t)
  return np.median(ts)
 def ref(A):
  w,v=np.linalg.eig(A); i=np.argmax(np.abs(w)); return w[i],v[:,i]
 def sc(A):
  w,v=sla.eig(A,check_finite=False,overwrite_a=True)
  i=np.argmax(np.abs(w)); return w[i],v[:,i]
 def sc2(A):
  w,v=sla.eig(A,check_finite=False)
  i=np.argmax(np.abs(w)); return w[i],v[:,i]
 def lap(A):
  wr,wi,vl,vr,info=dgeev(A,compute_vl=0,compute_vr=1,overwrite_a=1)
  i=np.argmax(wr*wr+wi*wi); l=complex(wr[i],wi[i])
  if wi[i]==0: v=vr[:,i].astype(complex)
  elif wi[i]>0: v=(vr[:,i]+1j*vr[:,i+1])
  else: v=(vr[:,i-1]-1j*vr[:,i])
  return l,v
 def lapev(A):
  wr,wi,vl,vr,info=dgeev(A,compute_vl=0,compute_vr=0,overwrite_a=1)
  i=np.argmax(wr*wr+wi*wi); return complex(wr[i],wi[i])
 print(n,'ref',bench(ref),'sc',bench(sc),'sc2',bench(sc2),'lap',bench(lap),'lapev',bench(lapev))
PY

